import{_ as i,o as s,c as t,a5 as e}from"./chunks/framework.C1a7WKBV.js";const c=JSON.parse('{"title":"VS Code 与 GitHub Copilot 入门","description":"从安装、登录到 Ask、Plan、Agent 模式，建立适合新手的可审查 AI 编程流程。","frontmatter":{"title":"VS Code 与 GitHub Copilot 入门","description":"从安装、登录到 Ask、Plan、Agent 模式，建立适合新手的可审查 AI 编程流程。"},"headers":[],"relativePath":"clients/vscode-copilot.md","filePath":"clients/vscode-copilot.md","lastUpdated":1788838685000}'),l={name:"clients/vscode-copilot.md"};function n(h,a,o,p,r,d){return s(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="vs-code-与-github-copilot-入门" tabindex="-1">VS Code 与 GitHub Copilot 入门 <a class="header-anchor" href="#vs-code-与-github-copilot-入门" aria-label="Permalink to &quot;VS Code 与 GitHub Copilot 入门&quot;">​</a></h1><p>VS Code + GitHub Copilot 适合第一次接触 AI 编程的人：文件、修改和终端都在同一个图形界面中，便于观察 AI 做了什么。Copilot Free 可用于体验，具体额度和功能以 <a href="https://docs.github.com/en/copilot/get-started/plans" target="_blank" rel="noreferrer">GitHub Copilot 官方方案</a>为准。</p><h2 id="_1-准备账户与软件" tabindex="-1">1. 准备账户与软件 <a class="header-anchor" href="#_1-准备账户与软件" aria-label="Permalink to &quot;1. 准备账户与软件&quot;">​</a></h2><ol><li>注册 <a href="https://github.com" target="_blank" rel="noreferrer">GitHub</a> 账户。</li><li>从 <a href="https://code.visualstudio.com/" target="_blank" rel="noreferrer">VS Code 官网</a> 安装最新版。</li><li>打开一个专门的练习文件夹，不要直接用桌面或用户主目录。</li></ol><p>按照 <a href="https://code.visualstudio.com/docs/setup/copilot" target="_blank" rel="noreferrer">VS Code 官方设置指南</a>，把鼠标移到状态栏的 Copilot 图标，选择 <strong>Use AI Features</strong>，按提示登录 GitHub。没有订阅的个人账户会进入可用的免费方案。</p><h2 id="_2-认识三个模式" tabindex="-1">2. 认识三个模式 <a class="header-anchor" href="#_2-认识三个模式" aria-label="Permalink to &quot;2. 认识三个模式&quot;">​</a></h2><p>根据 <a href="https://docs.github.com/en/copilot/how-tos/chat-with-copilot/chat-in-ide" target="_blank" rel="noreferrer">GitHub 官方 IDE 聊天文档</a>，常用模式分工如下：</p><table tabindex="0"><thead><tr><th>模式</th><th>适合做什么</th><th>是否改文件</th></tr></thead><tbody><tr><td>Ask</td><td>解释代码、查概念、定位可能原因</td><td>默认不改</td></tr><tr><td>Plan</td><td>分析复杂需求、列步骤、发现缺失信息</td><td>先不实现</td></tr><tr><td>Agent</td><td>多文件修改、运行命令、循环修复</td><td>会改，需审查</td></tr></tbody></table><p>新手的稳定顺序是 <strong>Ask 看懂 → Plan 定范围 → Agent 小步执行</strong>，不是所有任务直接扔给 Agent。</p><h2 id="_3-完成第一次可审查修改" tabindex="-1">3. 完成第一次可审查修改 <a class="header-anchor" href="#_3-完成第一次可审查修改" aria-label="Permalink to &quot;3. 完成第一次可审查修改&quot;">​</a></h2><h3 id="_3-1-建立练习文件" tabindex="-1">3.1 建立练习文件 <a class="header-anchor" href="#_3-1-建立练习文件" aria-label="Permalink to &quot;3.1 建立练习文件&quot;">​</a></h3><p>创建 <code>index.html</code>，输入：</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;!</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">doctype</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> html</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">html</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> lang</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;zh-CN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">head</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">meta</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> charset</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;UTF-8&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;我的练习&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">head</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">body</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;今天开始学习 AI 编程&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">body</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">html</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><h3 id="_3-2-用-ask-模式理解" tabindex="-1">3.2 用 Ask 模式理解 <a class="header-anchor" href="#_3-2-用-ask-模式理解" aria-label="Permalink to &quot;3.2 用 Ask 模式理解&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>解释当前 index.html 的结构。指出一个无障碍问题和一个视觉问题，不要修改文件。</span></span></code></pre></div><h3 id="_3-3-用-agent-模式修改" tabindex="-1">3.3 用 Agent 模式修改 <a class="header-anchor" href="#_3-3-用-agent-模式修改" aria-label="Permalink to &quot;3.3 用 Agent 模式修改&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>只修改 index.html：补充 viewport，增加清晰的页面结构和一个按钮。</span></span>
<span class="line"><span>不要引入框架或外部资源。完成后说明每处修改的理由。</span></span></code></pre></div><p>在编辑器中逐段查看差异。看不懂的改动不要直接接受，可以追问“这一行为什么需要”。</p><h3 id="_3-4-人工验证" tabindex="-1">3.4 人工验证 <a class="header-anchor" href="#_3-4-人工验证" aria-label="Permalink to &quot;3.4 人工验证&quot;">​</a></h3><p>用浏览器打开 <code>index.html</code>，检查标题、按钮、手机窗口和键盘 Tab 操作。AI 的文字说明不是验证结果，实际页面才是。</p><h2 id="_4-给项目建立长期规则" tabindex="-1">4. 给项目建立长期规则 <a class="header-anchor" href="#_4-给项目建立长期规则" aria-label="Permalink to &quot;4. 给项目建立长期规则&quot;">​</a></h2><p>在聊天中输入 <code>/init</code>，让 VS Code 分析代码库并创建自定义项目指令。官方指南说明该命令会根据项目生成适配的说明；生成后仍需人工检查。</p><p>规则至少包含：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 技术栈与版本</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 目录职责和禁止修改目录</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 命名、格式和语言规范</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 测试、类型检查、构建命令</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 完成任务时的汇报格式</span></span></code></pre></div><p>不要把密码、令牌、内部地址写进规则文件。</p><h2 id="_5-一套日常工作流" tabindex="-1">5. 一套日常工作流 <a class="header-anchor" href="#_5-一套日常工作流" aria-label="Permalink to &quot;5. 一套日常工作流&quot;">​</a></h2><ol><li><strong>同步现状</strong>：打开正确文件夹，确认 Git 状态干净。</li><li><strong>先问后改</strong>：让 Ask 模式解释相关模块和风险。</li><li><strong>限定范围</strong>：写明允许修改的文件与禁止事项。</li><li><strong>小步执行</strong>：一次只完成一个可验证目标。</li><li><strong>审查差异</strong>：在 Source Control 面板逐文件查看。</li><li><strong>运行验证</strong>：测试、类型检查、构建和人工体验都要做。</li><li><strong>保留回滚点</strong>：确认无误后再提交 Git。</li></ol><h2 id="_6-隐私与额度" tabindex="-1">6. 隐私与额度 <a class="header-anchor" href="#_6-隐私与额度" aria-label="Permalink to &quot;6. 隐私与额度&quot;">​</a></h2><p>VS Code 官方设置页说明，可以在设置中调整遥测和代码建议相关选项。工作或学校账户还可能受组织策略约束。开始前确认：</p><ul><li>当前登录的是个人账户还是组织账户。</li><li>项目是否允许发送到云端模型。</li><li>Agent 将执行哪些终端命令和外部调用。</li><li>当前模型或模式会消耗多少方案额度。</li></ul><p>敏感项目应先遵守组织政策；必须离线时，使用《<a href="/ai-handbook/clients/local-ai">Ollama 与 LM Studio</a>》中的本地方案。</p><h2 id="_7-常见问题" tabindex="-1">7. 常见问题 <a class="header-anchor" href="#_7-常见问题" aria-label="Permalink to &quot;7. 常见问题&quot;">​</a></h2><h3 id="_7-1-看不到-copilot-图标" tabindex="-1">7.1 看不到 Copilot 图标 <a class="header-anchor" href="#_7-1-看不到-copilot-图标" aria-label="Permalink to &quot;7.1 看不到 Copilot 图标&quot;">​</a></h3><p>先更新 VS Code，确认未设置 <code>chat.disableAIFeatures</code>，再检查扩展与 GitHub 登录状态。</p><h3 id="_7-2-agent-不运行命令" tabindex="-1">7.2 Agent 不运行命令 <a class="header-anchor" href="#_7-2-agent-不运行命令" aria-label="Permalink to &quot;7.2 Agent 不运行命令&quot;">​</a></h3><p>确认选择的是 Agent 模式，并检查工作区信任与工具权限。不要为了省一次确认而对陌生项目长期开放全部权限。</p><h3 id="_7-3-修改越来越乱" tabindex="-1">7.3 修改越来越乱 <a class="header-anchor" href="#_7-3-修改越来越乱" aria-label="Permalink to &quot;7.3 修改越来越乱&quot;">​</a></h3><p>停止继续追问，撤销到最近一个可运行状态。把任务缩小为一个文件或一个行为，并明确验收命令后重新开始。</p><h2 id="_8-完成标准" tabindex="-1">8. 完成标准 <a class="header-anchor" href="#_8-完成标准" aria-label="Permalink to &quot;8. 完成标准&quot;">​</a></h2><ul><li>[ ] 已登录 GitHub，能打开 Copilot Chat。</li><li>[ ] 能解释 Ask、Plan、Agent 的区别。</li><li>[ ] 完成一次小修改并逐行审查差异。</li><li>[ ] 用浏览器或测试命令实际验证结果。</li><li>[ ] 知道在哪里撤销改动与查看 Git 差异。</li></ul>`,40)])])}const g=i(l,[["render",n]]);export{c as __pageData,g as default};
